/// <summary>
/// Parent class to post the shipment
/// </summary>
abstract class METOrderShipmentConfirmation
{
    METSalesOrderShipmentLoadHeader        metSalesOrderShipmentLoadHeader;
    DocumentStatus      documentStatus;

}

Method.Source:
/// <summary>
/// Construct method for the class
/// </summary>
/// <param name = "_shipmentId">ShipmentId</param>
/// <returns>METOrderShipmentConfirmation</returns>
public static METOrderShipmentConfirmation construct(MetShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
    METOrderShipmentConfirmation    metOrderShipmentConfirmation;

    select firstonly metSalesOrderShipmentLoadHeader
            where metSalesOrderShipmentLoadHeader.ShipmentId == _shipmentId;

    if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
    {
        metOrderShipmentConfirmation = new METOrderShipmentConfirmation_SalesOrder(metSalesOrderShipmentLoadHeader);
    }
    else if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::TransferOrder)
    {
        metOrderShipmentConfirmation = new METOrderShipmentConfirmation_TransferOrder(metSalesOrderShipmentLoadHeader);
    }

    if (!_shipmentId)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return metOrderShipmentConfirmation;
}

/// <summary>
/// New method for class
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">ShipmentId reference</param>
protected void new(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    metSalesOrderShipmentLoadHeader = _metSalesOrderShipmentLoadHeader;
}

/// <summary>
/// Abstract method to have business logic for post method
/// </summary>
/// <returns>boolean value</returns>
abstract boolean post()
{
}

/// <summary>
/// Run method to initiate business logic
/// </summary>
public void run()
{
    boolean  result = false;

    ttsbegin;

    result = this.post();

    metSalesOrderShipmentLoadHeader.reread();

    if (result)
    {
        METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Shipped, documentStatus, metSalesOrderShipmentLoadHeader.ShipmentId);

        if (metSalesOrderShipmentLoadHeader.LoadStatus == MetLoadStatus::Shipped)
        {
            METSalesOrderShipmentLoadHeader::processsPickupAdvice(metSalesOrderShipmentLoadHeader.LoadId);
        }
    }
    else
    {
        METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Loaded, documentStatus, metSalesOrderShipmentLoadHeader.ShipmentId);
    }

    ttscommit;

    metSalesOrderShipmentLoadHeader.reread();

    if (metSalesOrderShipmentLoadHeader.ShipmentStatus == MetShipmentStatus::Shipped)
    {
        METTMSEngineExecutionMode tmpEngineExecutionMode;

        if (metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
        {
            tmpEngineExecutionMode = METTMSEngineExecutionMode::SalesOrderPackingSlip;
        }
        else
        {
            tmpEngineExecutionMode = METTMSEngineExecutionMode::TransferOrderShipped;
        }

        // CB626_TMSEngineSOPackingSlip Triggers for the TMS Engine processing on SO Delivery Note Posting
        // outside the ttscommit so in case of error does not rollback the packing slip posting
        METTMSEngineOrderProccess::construct(tmpEngineExecutionMode, metSalesOrderShipmentLoadHeader).run();
    }
    else if (metSalesOrderShipmentLoadHeader.ShipmentStatus != MetShipmentStatus::Shipped)
    {
        if (this.isShipmentNeedToReset(metSalesOrderShipmentLoadHeader))
        {
            METSalesOrderShipmentLoadHeader::updateDocStatusInHeader(MetShipmentStatus::Open, documentStatus, metSalesOrderShipmentLoadHeader.ShipmentId);
        }
    }

}

/// <summary>
/// Method to check whether shipment need to reset based on credit management
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader reference</param>
/// <returns>Boolean value</returns>
public boolean isShipmentNeedToReset(METSalesOrderShipmentLoadHeader    _metSalesOrderShipmentLoadHeader)
{
    METSalesOrderShipmentLoadLines   metSalesOrderShipmentLoadLines;
    SalesTable                       salesTable;
    boolean                          ret;

    if (_metSalesOrderShipmentLoadHeader.TransactionType == METOrderTransactionType::SalesOrder)
    {
        select firstonly1 salesTable
            where salesTable.CustAccount == _metSalesOrderShipmentLoadHeader.CustAccount &&
                 salesTable.CredManInCreditControl == NoYes::Yes
            exists join metSalesOrderShipmentLoadLines
                where metSalesOrderShipmentLoadLines.ShipmentId == _metSalesOrderShipmentLoadHeader.ShipmentId
                   && metSalesOrderShipmentLoadLines.OrderNum == salesTable.SalesId;

        ret = salesTable.RecId != 0;

        this.setUserAlert(_metSalesOrderShipmentLoadHeader.ShipmentId, "One of the sales order is in credit management hence shipment confirmation is failed.");
    }

    return ret;
}

public void setUserAlert(MetShipmentId _shipmentId, EventAlertedFor    _alertFor)
{
    UserInfo        userInfo;
    EventInbox      inbox;
    EventInboxId    inboxId;

    select firstonly1 userInfo 
        where UserInfo.id == CurUserId();

    inboxId = EventInbox::nextEventId();
    inbox.initValue();
    inbox.ShowPopup = NoYes::Yes; // To show Pop up
    inbox.Subject = strFmt("Shipment confirmation failed for '%1'.", _shipmentId);
    inbox.Message = "Testing Alerts";
    inbox.AlertedFor = _alertFor;
    inbox.SendEmail = false;
    inbox.UserId = UserInfo.Id;
    inbox.TypeId = classnum(EventType);
    inbox.AlertTableId = TableNum(METSalesOrderShipmentLoadHeader); // Table for which Alert is Generated
    inbox.AlertFieldId = fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId); // Field for which Alert is Generated
    inbox.TypeTrigger = EventTypeTrigger::FieldChanged;
    inbox.CompanyId = CurExt();
    inbox.InboxId = inboxId;
    //inbox.alert = systemdateget();
    //inbox.AlertCreateTime = timeNow();
    inbox.insert();



}
